function Header({active,setActive,user,onLogout,onUpdateUser,onSearch,onAlerts}:{active:Module,setActive:(m:Module)=>void,user:DemoUser,onLogout:()=>void,onUpdateUser:(u:DemoUser)=>void,onSearch:()=>void,onAlerts:()=>void}){
 const [mobileOpen,setMobileOpen]=useState(false); const [shiftOpen,setShiftOpen]=useState(false); const allowedNav=getNav(user); const [shift,setShift]=useState({shift:user.shift||'Mañana',start:user.shiftStart||'07:00',end:user.shiftEnd||'15:00'});
 const choose=(module:Module)=>{setActive(module);setMobileOpen(false)};
 return <><header><div className="brand"><span className="brandmark">S</span><span>Serena</span><small>Gestión integral</small></div><nav>{allowedNav.map(n=><button className={active===n.id?'active':''} onClick={()=>choose(n.id)} key={n.id}><n.icon size={17}/>{n.label}</button>)}</nav><div className="profile"><button className="icon" aria-label="Buscar" onClick={onSearch}><Search size={20}/></button><button className="icon has-dot" aria-label="Alertas" onClick={onAlerts}><Bell size={20}/></button>{['Enfermería','Asistente de geriatría'].includes(user.role)&&<button className="shift-button" onClick={()=>setShiftOpen(!shiftOpen)}><Clock size={14}/>{user.shift||'Asignar turno'}</button>}<span className="avatar user">{user.initials}</span><div><b>{user.name}</b><small>{user.role} · {user.shift?user.shiftStart+'–'+user.shiftEnd:'Demo'}</small></div><button className="logout" onClick={onLogout}>Salir</button></div></header>{shiftOpen&&<form className="shift-popover" onSubmit={e=>{e.preventDefault();onUpdateUser({...user,shift:shift.shift,shiftStart:shift.start,shiftEnd:shift.end});setShiftOpen(false)}}><b>Mi horario de trabajo</b><label>Piso asignado<select defaultValue={String(user.floors?.[0]||1)}>{[1,2,3,4,5].map(f=><option key={f} value={f}>Piso {f}</option>)}</select></label><label>Turno<select value={shift.shift} onChange={e=>setShift({...shift,shift:e.target.value})}><option>Mañana</option><option>Tarde</option><option>Noche</option><option>Personalizado</option></select></label><div><label>Desde<input type="time" value={shift.start} onChange={e=>setShift({...shift,start:e.target.value})}/></label><label>Hasta<input type="time" value={shift.end} onChange={e=>setShift({...shift,end:e.target.value})}/></label></div><button>Guardar asignación</button></form>}<div className="mobilebar"><button onClick={()=>setMobileOpen(!mobileOpen)} aria-label={mobileOpen?'Cerrar menú':'Abrir menú'} aria-expanded={mobileOpen}>{mobileOpen?<X/>:<Menu/>}</button><b>Serena</b><span>{user.role}</span></div>{mobileOpen&&<div className="mobilemenu"><div className="mobileuser"><span className="avatar user">{user.initials}</span><div><b>{user.name}</b><small>{user.role}{user.shift?' · '+user.shift+' '+user.shiftStart+'–'+user.shiftEnd:' · Demo'}</small></div></div>{allowedNav.map(n=><button className={active===n.id?'active':''} onClick={()=>choose(n.id)} key={n.id}><n.icon size={18}/><span>{n.label}</span>{active===n.id&&<Check size={16}/>}</button>)}<button onClick={onLogout}><X size={18}/><span>Cerrar sesión</span></button></div>}</>
}
const TaskCard=({icon:Icon,count,title,detail,tone,onClick}:{icon:any,count:number,title:string,detail:string,tone:string,onClick?:()=>void})=><button className={`task ${tone}`} onClick={onClick}><span className="task-icon"><Icon size={23}/></span><span className="task-copy"><small>{detail}</small><strong>{count}</strong><b>{title}</b></span><span className="arrow">→</span></button>;
function Dashboard({go,onNewEvent,onCare,user}:{go:(m:Module)=>void,onNewEvent:()=>void,onCare:(kind:'Catarsis'|'Baño'|'Caída'|'Curación')=>void,user:DemoUser}){
 const isAssistant=user.role==='Asistente de geriatría';const floor=user.floors?.[0];const canMedication=canManageMedication(user.role);const canVitals=['Administrador','Médica','Enfermería'].includes(user.role);const canDailyCare=['Administrador','Enfermería','Asistente de geriatría'].includes(user.role);const canCurations=['Administrador','Médica','Enfermería'].includes(user.role);const specialty=user.specialty;
 return <main><section className="welcome"><div><span className="eyebrow">ALERTAS · TURNO {user.shift?.toUpperCase()||'ACTIVO'}</span><h1>{floor?`Mi piso · Piso ${floor}`:'Alertas y pendientes'}</h1><p>Información breve para actuar · <b>{floor?'residentes asignados al piso '+floor:specialty?'seguimientos de '+specialty:'42 residentes activos'}</b></p></div><div className="shift"><span className="live"></span><div><small>Usuario activo</small><b>{user.name} · {user.role}</b></div><div className="progress"><i/></div></div></section>
 <section className="section-head"><div><h2>Requieren atención</h2><p>Fuera de rango, vencidos o sin registrar</p></div><button className="outline" onClick={onNewEvent}><ClipboardPlus size={18}/> Registrar evento</button></section>
 <div className="tasks">{canMedication&&<TaskCard icon={Pill} count={2} title="Medicaciones vencidas" detail="Sólo dosis fuera de horario" tone="red" onClick={()=>go('medicacion')}/>} {canVitals&&<TaskCard icon={HeartPulse} count={1} title="TA fuera de rango" detail="168/104 mmHg · Piso 2" tone="orange" onClick={()=>go('controles')}/>} {canDailyCare&&<TaskCard icon={Activity} count={2} title="Catarsis sin registro" detail="Más de 48 horas" tone="purple" onClick={()=>onCare('Catarsis')}/>} {canDailyCare&&<TaskCard icon={AlertTriangle} count={1} title="Caída sin evaluar" detail="Hoy 08:42 · Piso 3" tone="blue" onClick={()=>onCare('Caída')}/>} {specialty&&<TaskCard icon={FileHeart} count={2} title="Seguimientos pendientes" detail={specialty+' · historias clínicas'} tone="blue" onClick={()=>go('residentes')}/>}</div>
 {(canMedication||canDailyCare)&&<div className="dashboard-grid"><section className="panel medication"><div className="panel-title"><div><span className="mini pill"><Clock size={16}/></span><h3>Pendientes del turno</h3></div></div>{(isAssistant?[['Elena Rossi','Baño asignado','Piso 2 · Hab. 12 · Cama A'],['Elena Rossi','Catarsis sin registro','Último registro hace 2 días']]:[['Ofelia Suárez','Paracetamol 500 mg','Vencida hace 1 h 22 min'],['Elena Rossi','Control de TA','Valor previo fuera de rango']]).map(([name,task,detail])=>{const p=people.find(x=>x.name===name)!;return <div className="row" key={task}><Avatar p={p}/><div className="person"><b>{name}</b><small>{detail}</small></div><div className="drug"><b>{task}</b><small>Tocar para resolver</small></div><button className="confirm" onClick={()=>isAssistant?onCare(task.includes('Baño')?'Baño':'Catarsis'):go(task.includes('TA')?'controles':'medicacion')}>Resolver</button></div>})}</section>{canVitals&&<aside className="panel clinical"><div className="panel-title"><div><span className="mini heart"><AlertTriangle size={16}/></span><h3>Alertas clínicas</h3></div></div><div className="clinical-item danger"><div><b>TA fuera de rango</b><small>Elena Rossi · Piso 2 · Hab. 12 A</small></div><strong>168/104</strong><span>mmHg</span></div>{canCurations&&<div className="clinical-item"><div><b>Curación pendiente</b><small>Ofelia Suárez · Sacro</small></div><button className="status" onClick={()=>onCare('Curación')}>Registrar</button></div>}</aside>}</div>}
 <section className="quick"><h3>Accesos del perfil</h3><p>Acciones permitidas para {user.role}</p><div>{canVitals&&<button onClick={()=>go('controles')}><HeartPulse/>Signos vitales</button>}{canDailyCare&&<><button onClick={()=>onCare('Catarsis')}><Activity/>Catarsis</button><button onClick={()=>onCare('Baño')}><Bath/>Baños</button><button onClick={()=>onCare('Caída')}><AlertTriangle/>Caídas</button></>}{canCurations&&<button onClick={()=>onCare('Curación')}><FileHeart/>Curaciones</button>}{specialty&&<button onClick={()=>go('residentes')}><Users/>Abrir residentes y HCE</button>}</div></section></main>
}
function Medication({user}:{user:DemoUser}){
 const [adding,setAdding]=useState(false);const [view,setView]=useState(user.role==='Enfermería'?'mine':'all');const [residentFilter,setResidentFilter]=useState('Todos');const [query,setQuery]=useState('');const [statuses,setStatuses]=useState<Record<string,string>>({m1:'Administrada'});const [extra,setExtra]=useState<{resident:string,name:string,dose:string,route:string,time:string}[]>([]);const allowed=canManageMedication(user.role);const isNurse=user.role==='Enfermería';const baseRows=view==='mine'?roundMedications.filter(m=>m.assignedTo===user.email):roundMedications;const rows=baseRows.filter(m=>(residentFilter==='Todos'||m.resident===residentFilter)&&(m.resident+' '+m.name).toLowerCase().includes(query.toLowerCase()));const completed=rows.filter(m=>statuses[m.id]).length;const setStatus=(id:string,status:string)=>setStatuses({...statuses,[id]:status});
 return <main><section className="page-title"><div><span className="eyebrow">ADMINISTRACIÓN SEGURA · TURNO ACTIVO</span><h1>{view==='mine'?'Mi ronda de medicación':'Medicación'}</h1><p>{view==='mine'?`${new Set(rows.map(r=>r.resident)).size} residentes asignados · ${rows.length} dosis del horario activo`:'Planilla general de residentes y medicación indicada.'}</p></div><div><button className="outline" onClick={()=>window.print()}>Imprimir plan</button>{allowed&&<button className="primary" onClick={()=>setAdding(true)}><Plus size={18}/> Agregar medicación</button>}</div></section>
 <section className="round-controls"><div className="view-tabs">{isNurse&&<button className={view==='mine'?'active':''} onClick={()=>setView('mine')}>Mi ronda</button>}<button className={view==='all'?'active':''} onClick={()=>setView('all')}>Todos los residentes</button></div><div className="round-progress"><div><b>{completed} de {rows.length} dosis resueltas</b><small>{rows.length-completed} pendientes · horario 10:00</small></div><span><i style={{width:`${rows.length?completed/rows.length*100:0}%`}}/></span></div></section>
 <div className="toolbar"><div className="seg"><button>06:00</button><button className="sel">08:00</button><button>10:00</button><button>12:00</button><button>14:00</button><button>16:00</button><button>18:00</button><button>20:00</button><button>22:00</button><button>24:00</button></div><select value={residentFilter} onChange={e=>setResidentFilter(e.target.value)}><option>Todos</option>{people.map(p=><option key={p.name}>{p.name}</option>)}</select><label><Search size={17}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar residente o medicamento"/></label></div>
 <section className="round-list">{rows.map((m,index)=>{const p=people.find(person=>person.name===m.resident)!;const status=statuses[m.id];return <article className={`round-item ${status?'resolved':''}`} key={m.id}><div className="round-order">{index+1}</div><Avatar p={p}/><div className="round-resident"><b>{m.resident}</b><small>Habitación {m.room} · {m.time}</small></div><div className="round-drug"><b>{m.name} <strong>{m.dose}</strong></b><span>{m.form} · Vía {m.route}</span><small className={m.instruction.includes('Requiere')||m.instruction.includes('Controlar')?'clinical-warning':''}>{m.instruction}</small></div><div className="round-action">{status?<><span className={`status-result ${status.toLowerCase().replaceAll(' ','-')}`}><Check size={15}/>{status}</span><small>{user.initials} · 09:{56-index}</small><button onClick={()=>setStatus(m.id,'')}>Deshacer</button></>:<><button className="administer" onClick={()=>setStatus(m.id,'Administrada')}><Check size={17}/> Administrada</button><select aria-label={`Otra opción para ${m.name}`} defaultValue="" onChange={e=>{if(e.target.value)setStatus(m.id,e.target.value)}}><option value="" disabled>Otra opción…</option><option>Rechazada</option><option>Ausente</option><option>Omitida por indicación médica</option><option>No disponible</option></select></>}</div></article>})}{extra.map((m,i)=><article className="round-item" key={`${m.resident}-${i}`}><div className="round-order">N</div><span className="avatar">+</span><div className="round-resident"><b>{m.resident}</b><small>Nueva indicación · {m.time}</small></div><div className="round-drug"><b>{m.name} <strong>{m.dose}</strong></b><span>Vía {m.route}</span><small>Cargada por {user.name}</small></div><div className="round-action"><button className="administer">Pendiente</button></div></article>)}</section>
 <div className="round-legend"><span><i className="ok"/>Administrada</span><span><i className="pending"/>Pendiente</span><span><i className="alert"/>Requiere control</span><small>Cada acción registra usuario, fecha y hora automáticamente.</small></div>{adding&&<MedicationEditor onClose={()=>setAdding(false)} onSave={m=>{setExtra([...extra,m]);setAdding(false)}}/>}</main>
}
function MedicationEditor({onClose,onSave}:{onClose:()=>void,onSave:(m:{resident:string,name:string,dose:string,route:string,time:string})=>void}){const [m,setM]=useState({resident:people[0].name,name:'',dose:'',route:'Oral',time:'08:00',observation:'',allergyChecked:false,rescue:false,preBath:false});return <div className="modal-backdrop"><form className="editor editor-wide" onSubmit={e=>{e.preventDefault();onSave(m)}}><div className="editor-head"><div><span className="eyebrow">INDICACIÓN MÉDICA</span><h2>Agregar medicación al paciente</h2></div><button type="button" onClick={onClose}><X/></button></div><div className="form-grid"><label>Residente<select value={m.resident} onChange={e=>setM({...m,resident:e.target.value})}>{people.map(p=><option key={p.name}>{p.name} · Piso {p.floor} · {p.room} {p.bed}</option>)}</select></label><label>Medicamento<input value={m.name} onChange={e=>setM({...m,name:e.target.value})} required/></label><label>Dosis y presentación<input value={m.dose} onChange={e=>setM({...m,dose:e.target.value})} placeholder="Ej. 500 mg · 1 comprimido" required/></label><label>Vía<select value={m.route} onChange={e=>setM({...m,route:e.target.value})}><option>Oral</option><option>Gastrostomía</option><option>Subcutánea</option><option>Intramuscular</option><option>Tópica</option><option>Otra</option></select></label><label>Horario<input type="time" value={m.time} onChange={e=>setM({...m,time:e.target.value})}/></label><label>Frecuencia<select><option>Diaria</option><option>Cada 8 horas</option><option>Cada 12 horas</option><option>Según necesidad</option><option>Única vez</option></select></label><label className="wide">Observaciones e indicaciones<input value={m.observation} onChange={e=>setM({...m,observation:e.target.value})} placeholder="Con alimento, controlar TA/HGT, forma de administración…"/></label><label className="checkbox-line"><input type="checkbox" checked={m.allergyChecked} onChange={e=>setM({...m,allergyChecked:e.target.checked})} required/> Alergias verificadas</label><label className="checkbox-line"><input type="checkbox" checked={m.rescue} onChange={e=>setM({...m,rescue:e.target.checked})}/> Medicación de rescate</label><label className="checkbox-line"><input type="checkbox" checked={m.preBath} onChange={e=>setM({...m,preBath:e.target.checked})}/> Previa al baño</label></div><div className="editor-footer"><small>La administración registrará enfermera, fecha, hora, turno y observaciones.</small><button type="button" onClick={onClose}>Cancelar</button><button className="primary">Guardar indicación</button></div></form></div>}
function Controls({user}:{user:DemoUser}){const [saved,setSaved]=useState(false);const [shift,setShift]=useState(user.shift||'Mañana');const canEdit=['Administrador','Médica','Enfermería'].includes(user.role);return <main><section className="page-title"><div><span className="eyebrow">PLANILLA DE SIGNOS VITALES</span><h1>Signos vitales</h1><p>TA, temperatura, SatO₂, FC y HGT por turno.</p></div><button className="outline" onClick={()=>window.print()}>Imprimir planilla</button></section><div className="view-tabs">{['Mañana','Tarde','Noche'].map(t=><button key={t} className={shift===t?'active':''} onClick={()=>setShift(t)}>{t}</button>)}</div><section className="panel vitals"><div className="tablehead six"><span>Residente / ubicación</span><span>TA</span><span>FC</span><span>Temp.</span><span>Sat. O₂</span><span>HGT</span></div>{people.map((p,i)=><div className="vitalrow" key={p.name}><div><Avatar p={p}/><p><b>{p.name}</b><small>Piso {p.floor} · Hab. {p.room} · Cama {p.bed}</small></p></div><input disabled={!canEdit} className={i===0?'warn':''} defaultValue={i===0?'168/104':''} placeholder="— / —"/><input disabled={!canEdit} defaultValue={i===0?'82':''} placeholder="—"/><input disabled={!canEdit} defaultValue={i===0?'36.7':''} placeholder="—"/><input disabled={!canEdit} defaultValue={i===0?'96':''} placeholder="—"/><input disabled={!canEdit} placeholder={p.risk==='Diabetes'?'mg/dl':'Opcional'}/></div>)}</section>{canEdit&&<div className="savebar"><span>{saved?`✓ Planilla de turno ${shift} firmada por ${user.name}`:'Los cambios guardan usuario, fecha y turno'}</span><button onClick={()=>setSaved(true)}>Guardar y firmar</button></div>}</main>}
function Residents({onOpenHce,user}:{onOpenHce:(resident:string)=>void,user:DemoUser}){
 const [records,setRecords]=useState(people); const [selected,setSelected]=useState(people[0]); const [editing,setEditing]=useState(false); const [query,setQuery]=useState('');
 const visible=records.filter(p=>(p.name+' '+p.floor+' '+p.room+' '+p.bed+' '+p.risk).toLowerCase().includes(query.toLowerCase()));
 const saveResident=(data:Partial<typeof selected>)=>{const next={...selected,...data};setRecords(records.map(p=>p.name===selected.name?next:p));setSelected(next);setEditing(false)};
 const deactivate=()=>{if(!window.confirm('¿Dar de baja a '+selected.name+'? Su historia clínica se conservará.'))return;const remaining=records.filter(p=>p.name!==selected.name);setRecords(remaining);if(remaining[0])setSelected(remaining[0])};
 const deleteContact=(name:string)=>{if(!window.confirm('¿Eliminar el contacto '+name+'?'))return;const next={...selected,contacts:selected.contacts.filter(c=>c.name!==name)};setRecords(records.map(p=>p.name===selected.name?next:p));setSelected(next)};
 return <main><PageTitle eyebrow="PADRÓN ACTIVO" title="Residentes" text={records.length+' residentes visibles · fichas clínicas y administrativas conectadas.'}/><div className="residents-layout"><section className="panel resident-list"><label><Search size={17}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar por nombre, DNI o habitación"/></label>{visible.map(p=><button onClick={()=>setSelected(p)} className={selected.name===p.name?'selected':''} key={p.name}><Avatar p={p}/><span><b>{p.name}</b><small>Piso {p.floor} · Hab. {p.room} · Cama {p.bed} · {p.age} años</small></span><em>{p.risk}</em></button>)}{visible.length===0&&<p className="empty-copy">No se encontraron residentes.</p>}</section><section className="profile-card"><div className="record-actions"><button onClick={()=>window.print()}>Imprimir ficha</button><button onClick={()=>setEditing(true)}><Pencil size={14}/> Editar datos</button><button className="danger-action" onClick={deactivate}><Trash2 size={14}/> Dar de baja</button></div><div className="profile-top"><Avatar p={selected}/><div><small>PISO {selected.floor} · HABITACIÓN {selected.room} · CAMA {selected.bed}</small><h2>{selected.name}</h2><p>{selected.age} años · DNI 14.403.911</p></div>{user.role!=='Asistente de geriatría'&&<button onClick={()=>onOpenHce(selected.name)}>Ver HCE completa</button>}</div><div className="facts resident-facts"><article><small>Obra social / cobertura</small><b>{selected.insurance}</b></article><article><small>Ubicación asistencial</small><b>Piso {selected.floor} · Hab. {selected.room} · Cama {selected.bed}</b></article><article><small>Alergias</small><b>Penicilina</b></article><article><small>Condición relevante</small><b>{selected.risk}</b></article></div><div className="profile-columns"><section className="family"><div className="subhead"><div><h3>Contactos familiares</h3><small>Orden de contacto ante una emergencia</small></div><button><Plus size={14}/> Agregar</button></div>{selected.contacts.map((contact,index)=><article key={contact.name}><span className="contact-order">{index+1}</span><div><b>{contact.name}</b><small>{contact.relation}{contact.primary?' · Contacto principal':''}</small></div><a href={'tel:'+contact.phone.replaceAll(' ','')}>{contact.phone}</a><div className="inline-actions"><button aria-label={'Editar '+contact.name}><Pencil size={13}/></button><button aria-label={'Eliminar '+contact.name} onClick={()=>deleteContact(contact.name)}><Trash2 size={13}/></button></div></article>)}</section><section><h3>Actividad de hoy</h3><div className="timeline"><p><i className="green"/><b>09:56</b> Medicación administrada <small>por Marina López</small></p><p><i className="blue"/><b>09:12</b> Signos vitales registrados <small>TA 128/78 · Sat. 96%</small></p><p><i className="purple"/><b>08:15</b> Desayuno y catarsis <small>por Ana Torres</small></p></div></section></div></section></div>{editing&&<ResidentEditor resident={selected} onClose={()=>setEditing(false)} onSave={saveResident}/>}</main>
}

function ResidentEditor({resident,onClose,onSave}:{resident:typeof people[0],onClose:()=>void,onSave:(data:Partial<typeof resident>)=>void}){const [form,setForm]=useState({name:resident.name,floor:String(resident.floor),room:resident.room,bed:resident.bed,age:String(resident.age),insurance:resident.insurance,risk:resident.risk});const change=(key:keyof typeof form,value:string)=>setForm({...form,[key]:value});return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><form className="editor" onSubmit={e=>{e.preventDefault();onSave({...form,age:Number(form.age),floor:Number(form.floor),initials:form.name.split(' ').map(n=>n[0]).join('').slice(0,2).toUpperCase()})}}><div className="editor-head"><div><span className="eyebrow">DATOS DEL RESIDENTE</span><h2>Editar ficha</h2></div><button type="button" onClick={onClose} aria-label="Cerrar"><X/></button></div><div className="form-grid"><label>Nombre completo<input value={form.name} onChange={e=>change('name',e.target.value)} required/></label><label>Piso<select value={form.floor} onChange={e=>change('floor',e.target.value)}>{[1,2,3,4,5].map(f=><option key={f}>{f}</option>)}</select></label><label>Habitación<input value={form.room} onChange={e=>change('room',e.target.value)} required/></label><label>Cama<input value={form.bed} onChange={e=>change('bed',e.target.value)} required/></label><label>Edad<input type="number" value={form.age} onChange={e=>change('age',e.target.value)} required/></label><label>Condición relevante<input value={form.risk} onChange={e=>change('risk',e.target.value)}/></label><label className="wide">Obra social / Nº de afiliado<input value={form.insurance} onChange={e=>change('insurance',e.target.value)} required/></label></div><div className="editor-footer"><small>La modificación quedará registrada a nombre de Marina López.</small><button type="button" onClick={onClose}>Cancelar</button><button className="primary" type="submit">Guardar cambios</button></div></form></div>}
function ClinicalHistory({user,resident}:{user:DemoUser,resident:string}){
 const editable=canWriteHce(user.role);
 const [files,setFiles]=useState<{name:string,size:string,type:string,by:string}[]>([{name:'Epicrisis_ingreso.pdf',size:'1,2 MB',type:'PDF',by:'Dra. Julia Ferrer'},{name:'Radiografia_torax.jpg',size:'860 KB',type:'Imagen',by:'Marina López'},{name:'Plan_nutricional.xlsx',size:'42 KB',type:'Excel',by:'Lic. Nutrición'}]); const [message,setMessage]=useState(''); const [section,setSection]=useState<'evoluciones'|'valoracion'|'equipo'>('evoluciones'); const [adding,setAdding]=useState(false); const [entries,setEntries]=useState([{section:'evoluciones',title:'Control médico programado',detail:'Paciente lúcida, afebril y hemodinámicamente estable.',by:'Dra. Julia Ferrer',date:'Hoy · 09:30'},{section:'valoracion',title:'Índice de Katz · A',detail:'Independiente para actividades básicas de la vida diaria.',by:'Lic. Terapia Ocupacional',date:'8 sep · 15:20'},{section:'equipo',title:'Seguimiento nutricional',detail:'Buena tolerancia al plan alimentario. Mantener aporte proteico.',by:'Lic. Nutrición',date:'7 sep · 11:10'}]);
 const addFiles=(list:FileList|null)=>{if(!list)return;const accepted=['pdf','jpg','jpeg','png','webp','mp4','webm','doc','docx','xls','xlsx','csv','txt'];const max=50*1024*1024;const valid=[...list].filter(f=>accepted.includes(f.name.split('.').pop()?.toLowerCase()||'')&&f.size<=max);setMessage(valid.length!==list.length?'Algunos archivos fueron rechazados por tipo o tamaño (máximo 50 MB).':valid.length+' archivo(s) agregado(s) correctamente.');setFiles([...files,...valid.map(f=>({name:f.name,size:f.size>1048576?(f.size/1048576).toFixed(1)+' MB':Math.ceil(f.size/1024)+' KB',type:fileType(f.name),by:user.name}))])};
 const labels={evoluciones:['Evoluciones médicas','Etiquetado para epicrisis'],valoracion:['Valoración integral','Pfeiffer, MMSE, MoCA, Katz y Norton'],equipo:['Equipo interdisciplinario','Nutrición, kinesiología, psicología y más']};
 return <main><section className="page-title"><div><span className="eyebrow">HISTORIA CLÍNICA ELECTRÓNICA</span><h1>Historia clínica</h1><p>{resident} · Evoluciones, estudios y documentos vinculados.</p></div><div><button className="outline" onClick={()=>window.print()}>Imprimir HCE</button>{editable&&<button className="primary" onClick={()=>setAdding(true)}><Plus size={18}/> Nuevo registro</button>}</div></section><div className="modulecards hce-modules">{([['evoluciones',Stethoscope],['valoracion',FileHeart],['equipo',Users]] as const).map(([id,I])=><button className={section===id?'selected-module':''} key={id} onClick={()=>setSection(id)}><I/><span><b>{labels[id][0]}</b><small>{labels[id][1]}</small></span>→</button>)}</div><section className="panel record-section"><div className="panel-title"><div><h2>{labels[section][0]}</h2><small>Registros clínicos de {resident}</small></div>{editable&&<button onClick={()=>setAdding(true)}>Agregar →</button>}</div>{entries.filter(e=>e.section===section).map((entry,i)=><article className="record-entry" key={entry.title+i}><span className="record-mark"><FileHeart size={18}/></span><div><b>{entry.title}</b><p>{entry.detail}</p><small>{entry.by} · {entry.date}</small></div></article>)}</section>{section==='valoracion'&&<section className="panel assessment"><div className="panel-title"><div><h2>Valoración geriátrica integral</h2><small>Escalas editables del modelo institucional</small></div></div><div className="assessment-grid"><fieldset><legend>Índice de Katz</legend>{['Alimentación','Higiene','Continencia','Vestido','Movilidad'].map(x=><label key={x}>{x}<select disabled={!editable}><option>0 · Independiente</option><option>1 · Ayuda mínima</option><option>2 · Ayuda moderada</option><option>3 · Dependiente</option><option>4 · Dependencia total</option></select></label>)}</fieldset><fieldset><legend>Pfeiffer · 10 preguntas</legend>{['Fecha actual','Día de la semana','Lugar actual','Teléfono/dirección','Edad','Fecha de nacimiento','Presidente actual','Presidente anterior','Apellido materno','Restar de 3 en 3'].map((x,i)=><label className="checkbox-line" key={x}><input type="checkbox" disabled={!editable}/> {i+1}. {x} · error</label>)}<small>0–2 normal · 3–7 deterioro leve/moderado · 8–10 severo</small></fieldset><fieldset><legend>Escala de Norton</legend>{['Estado físico','Estado mental','Movilidad','Actividad','Continencia'].map(x=><label key={x}>{x}<select disabled={!editable}><option>4 · Bueno</option><option>3 · Mediano</option><option>2 · Regular</option><option>1 · Muy malo</option></select></label>)}<small>Riesgo moderado: &lt;16 · alto: &lt;12</small></fieldset><fieldset><legend>Evaluación integral</legend>{['Riesgo de caídas','Alimentación','Dolor','AIVD','Entorno social/familiar','Procedencia'].map(x=><label key={x}>{x}<input disabled={!editable}/></label>)}</fieldset></div></section>}<section className="attachments panel"><div className="attachments-head"><div><h2>Archivos adjuntos</h2><p>Estudios, imágenes, videos y documentación clínica.</p></div><label className="upload-button"><Upload size={16}/> Agregar archivos<input type="file" multiple accept=".pdf,.jpg,.jpeg,.png,.webp,.mp4,.webm,.doc,.docx,.xls,.xlsx,.csv,.txt" onChange={e=>addFiles(e.target.files)}/></label></div>{message&&<div className="upload-message">{message}</div>}<div className="file-table"><div className="file-row file-header"><span>Archivo</span><span>Tipo</span><span>Cargado por</span><span>Tamaño</span><span>Acciones</span></div>{files.map((f,i)=><div className="file-row" key={f.name+i}><div className="file-name">{f.type==='Imagen'?<Image/>:f.type==='Video'?<Video/>:f.type==='PDF'?<FileText/>:<File/>}<b>{f.name}</b></div><span>{f.type}</span><span>{f.by}</span><span>{f.size}</span><div className="inline-actions"><button aria-label={'Ver '+f.name}>Ver</button><button aria-label={'Eliminar '+f.name} onClick={()=>{if(window.confirm('¿Anular este archivo de la historia clínica?'))setFiles(files.filter((_,index)=>index!==i))}}><Trash2 size={13}/></button></div></div>)}</div></section>{adding&&editable&&<HceEditor section={section} user={user} onClose={()=>setAdding(false)} onSave={entry=>{setEntries([entry,...entries]);setAdding(false)}}/>}</main>
}
function fileType(name:string){const ext=name.split('.').pop()?.toLowerCase();if(['jpg','jpeg','png','webp'].includes(ext||''))return'Imagen';if(['mp4','webm'].includes(ext||''))return'Video';if(ext==='pdf')return'PDF';if(['doc','docx'].includes(ext||''))return'Word';if(['xls','xlsx','csv'].includes(ext||''))return'Excel';return'Otro'}
function CareRecords({initialKind,onKindUsed,user}:{initialKind:'Catarsis'|'Baño'|'Caída'|'Curación'|null,onKindUsed:()=>void,user:DemoUser}){
 const [kind,setKind]=useState<'Catarsis'|'Baño'|'Caída'|'Curación'>(initialKind||'Catarsis'); const [adding,setAdding]=useState(Boolean(initialKind)); const [records,setRecords]=useState([{kind:'Catarsis',resident:'Elena Rossi',detail:'Bristol 4 · espontánea',time:'Hoy · 08:15'},{kind:'Baño',resident:'Manuel Pereyra',detail:'Realizado · ducha · asistencia parcial',time:'Hoy · 08:05'},{kind:'Caída',resident:'Ofelia Suárez',detail:'Sin lesión aparente · médica y familiar notificados',time:'Hoy · 08:42'},{kind:'Curación',resident:'Ofelia Suárez',detail:'UPP sacra · limpieza y apósito',time:'Ayer · 18:20'}]);
 React.useEffect(()=>{if(initialKind){setKind(initialKind);setAdding(true);onKindUsed()}},[initialKind,onKindUsed]);
 const modules=[[Activity,'Catarsis','Registro diario y escala de Bristol'],[Bath,'Baño','Asignación por turno · sí/no'],[AlertTriangle,'Caída','Evaluación completa del evento'],[FileHeart,'Curación','Úlceras por presión y curaciones']] as const;
 return <main><section className="page-title"><div><span className="eyebrow">CUIDADOS · PISOS 1 A 5</span><h1>Cuidados diarios</h1><p>Registros simples, trazables y filtrados por perfil.</p></div><div><button className="outline" onClick={()=>window.print()}>Imprimir</button><button className="primary" onClick={()=>setAdding(true)}><Plus size={18}/> Registrar</button></div></section><div className="modulecards">{modules.map(([I,t,d])=><button className={kind===t?'selected-module':''} key={t} onClick={()=>setKind(t)}><I/><span><b>{t==='Baño'?'Baños':t==='Caída'?'Caídas':t==='Curación'?'Curaciones':t}</b><small>{d}</small></span>→</button>)}</div><section className="panel care-list"><div className="panel-title"><div><h2>Registros de {kind.toLowerCase()}</h2><small>{user.shift||'Turno activo'} · {user.floors?.length?'Piso '+user.floors.join(', '):'Todos los pisos'}</small></div><button onClick={()=>setAdding(true)}>Nuevo →</button></div>{records.filter(r=>r.kind===kind).map((r,i)=>{const p=people.find(x=>x.name===r.resident)||people[0];return <article className="care-entry" key={r.kind+r.resident+i}><Avatar p={p}/><div><b>{r.resident}</b><p>{r.detail}</p><small>Piso {p.floor} · Hab. {p.room} · Cama {p.bed} · {r.time}</small></div><span className="status mint">Registrado</span></article>})}</section>{adding&&<CareEditor kind={kind} user={user} onClose={()=>setAdding(false)} onSave={record=>{setRecords([record,...records]);setAdding(false)}}/>}</main>
}
function PageTitle({eyebrow,title,text}:{eyebrow:string,title:string,text:string}){return <section className="page-title"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{text}</p></div><button className="primary"><Plus size={18}/> Nuevo registro</button></section>}
function AlertDock({open,onClose,onNavigate}:{open:boolean,onClose:()=>void,onNavigate:(module:Module)=>void}){return <div className={'alertdock '+(open?'open':'')}><button className="alerttab" onClick={()=>open?onClose():null}><span><Bell size={18}/><b>6 alertas activas</b></span><small>2 requieren atención inmediata</small><ChevronDown size={18}/></button>{open&&<div className="alertcontent"><button onClick={()=>{onNavigate('medicacion');onClose()}}><span className="dot red"/><div><b>Medicación vencida</b><small>Ofelia Suárez · Paracetamol · hace 1 h 22 min</small></div>→</button><button onClick={()=>{onNavigate('controles');onClose()}}><span className="dot orange"/><div><b>TA fuera de rango</b><small>Elena Rossi · 168/104 mmHg</small></div>→</button><button onClick={onClose} className="close" aria-label="Cerrar alertas"><X/></button></div>}</div>}
type HceSection='evoluciones'|'valoracion'|'equipo';
function HceEditor({section,user,onClose,onSave}:{section:HceSection,user:DemoUser,onClose:()=>void,onSave:(entry:{section:HceSection,title:string,detail:string,by:string,date:string})=>void}){const defaults={evoluciones:'Evolución clínica',valoracion:'Valoración geriátrica integral',equipo:user.specialty?`Seguimiento de ${user.specialty}`:'Interconsulta interdisciplinaria'};const [title,setTitle]=useState(defaults[section]);const [detail,setDetail]=useState('');return <div className="modal-backdrop"><form className="editor editor-wide" onSubmit={e=>{e.preventDefault();onSave({section,title,detail,by:user.name,date:'Ahora'})}}><div className="editor-head"><div><span className="eyebrow">HISTORIA CLÍNICA · RESIDENTE IDENTIFICADO</span><h2>Nuevo registro</h2></div><button type="button" onClick={onClose}><X/></button></div><div className="form-grid"><label className="wide">Título<input value={title} onChange={e=>setTitle(e.target.value)} required/></label>{section==='evoluciones'&&<><label>Motivo / antecedente<input placeholder="Motivo de evaluación"/></label><label>Alergias<input placeholder="Alergias conocidas"/></label><label>TA / FC<input placeholder="120/80 · 72 lpm"/></label><label>Temp. / SatO₂<input placeholder="36,5 °C · 97%"/></label><label>Cardiovascular<input/></label><label>Respiratorio<input/></label><label>Abdominal<input/></label><label>Neurológico<input/></label><label>Piel<input/></label><label>Último laboratorio<input type="date"/></label><label>Última internación<input type="date"/></label><label>Cirugías / antecedentes<input/></label></>}{section==='equipo'&&<><label>Disciplina<input value={user.specialty||user.role} readOnly/></label><label>Objetivo del seguimiento<input/></label><label>Plan / frecuencia<input/></label><label>Respuesta del residente<input/></label></>}<label className="wide">Evolución, examen y conducta<textarea value={detail} onChange={e=>setDetail(e.target.value)} rows={6} required/></label></div><div className="editor-footer"><small>Firma digital: {user.name} · {user.role}</small><button type="button" onClick={onClose}>Cancelar</button><button className="primary">Guardar y firmar</button></div></form></div>}
function CareEditor({kind,user,onClose,onSave}:{kind:'Catarsis'|'Baño'|'Caída'|'Curación',user:DemoUser,onClose:()=>void,onSave:(record:{kind:string,resident:string,detail:string,time:string})=>void}){const [resident,setResident]=useState(people[0].name);const [bristol,setBristol]=useState('4');const [done,setDone]=useState('Sí');const [observation,setObservation]=useState('');const p=people.find(x=>x.name===resident)!;const save=()=>{const detail=kind==='Catarsis'?`Bristol ${bristol} · ${observation||'sin observaciones'}`:kind==='Baño'?`${done==='Sí'?'Realizado':'No realizado'} · ${observation||'sin observaciones'}`:kind==='Caída'?`${observation||'Evaluación registrada'}`:`Curación · ${observation||'procedimiento registrado'}`;onSave({kind,resident,detail,time:'Ahora · '+user.name})};return <div className="modal-backdrop"><form className="editor editor-wide" onSubmit={e=>{e.preventDefault();save()}}><div className="editor-head"><div><span className="eyebrow">CUIDADOS DEL TURNO</span><h2>Registrar {kind.toLowerCase()}</h2></div><button type="button" onClick={onClose}><X/></button></div><div className="resident-context"><b>{resident}</b><span>Piso {p.floor} · Habitación {p.room} · Cama {p.bed}</span></div><div className="form-grid"><label>Residente<select value={resident} onChange={e=>setResident(e.target.value)}>{people.map(x=><option key={x.name}>{x.name}</option>)}</select></label><label>Fecha y hora<input type="datetime-local" required/></label>{kind==='Catarsis'&&<><label>Resultado<select><option>Positiva</option><option>Negativa</option><option>Sin registro</option></select></label><label>Escala de Bristol<select value={bristol} onChange={e=>setBristol(e.target.value)}>{[1,2,3,4,5,6,7].map(n=><option key={n} value={n}>Tipo {n}</option>)}</select></label><label>Características<select><option>Normal</option><option>Dura</option><option>Líquida</option><option>Con sangre</option><option>Con moco</option></select></label></>}{kind==='Baño'&&<><label>¿Baño realizado?<select value={done} onChange={e=>setDone(e.target.value)}><option>Sí</option><option>No</option></select></label><label>Tipo<select><option>Ducha</option><option>En cama</option><option>Higiene parcial</option></select></label><label>Asistencia<select><option>Total</option><option>Parcial</option><option>Independiente</option></select></label><label>Asistente responsable<input value={user.name} readOnly/></label><label>Enfermera supervisora<input placeholder="Nombre y firma"/></label></>}{kind==='Caída'&&<><label>Lugar<input placeholder="Habitación, baño, pasillo…" required/></label><label>Mecanismo<select><option>Desde propia altura</option><option>Desde cama</option><option>Desde silla</option><option>Otro</option></select></label><label>Lesión visible<select><option>No</option><option>Sí</option></select></label><label>Dolor<select><option>No</option><option>Leve</option><option>Moderado</option><option>Intenso</option></select></label><label>Signos vitales posteriores<input placeholder="TA · FC · SatO₂ · Temp."/></label><label>Conducta tomada<input placeholder="Evaluación, traslado, control…" required/></label><label className="checkbox-line"><input type="checkbox"/> Médico notificado</label><label className="checkbox-line"><input type="checkbox"/> Familiar notificado</label></>}{kind==='Curación'&&<><label>Tipo de lesión<select><option>Úlcera por presión</option><option>Herida</option><option>Escoriación</option><option>Otra</option></select></label><label>Localización<input placeholder="Sacro, talón, miembro…" required/></label><label>Estadio<select><option>Sin estadificar</option><option>I</option><option>II</option><option>III</option><option>IV</option></select></label><label>Material / procedimiento<input placeholder="Limpieza, apósito, crema…" required/></label></>}<label className="wide">Observaciones<textarea value={observation} onChange={e=>setObservation(e.target.value)} rows={3}/></label></div><div className="editor-footer"><small>Se registrarán usuario, rol, fecha, hora, turno y ubicación.</small><button type="button" onClick={onClose}>Cancelar</button><button className="primary">Guardar y firmar</button></div></form></div>}
function EventEditor({onClose,onSave}:{onClose:()=>void,onSave:(message:string)=>void}){const [resident,setResident]=useState(people[0].name);const [type,setType]=useState('Observación general');const [detail,setDetail]=useState('');return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><form className="editor" onSubmit={e=>{e.preventDefault();onSave(type+' de '+resident+' registrada correctamente.')}}><div className="editor-head"><div><span className="eyebrow">EVENTO DEL TURNO</span><h2>Registrar nuevo evento</h2></div><button type="button" onClick={onClose} aria-label="Cerrar"><X/></button></div><div className="form-grid"><label>Residente<select value={resident} onChange={e=>setResident(e.target.value)}>{people.map(p=><option key={p.name}>{p.name}</option>)}</select></label><label>Tipo<select value={type} onChange={e=>setType(e.target.value)}><option>Observación general</option><option>Novedad clínica</option><option>Contacto familiar</option><option>Incidente</option><option>Tarea pendiente</option></select></label><label className="wide">Detalle<textarea value={detail} onChange={e=>setDetail(e.target.value)} rows={5} required/></label></div><div className="editor-footer"><button type="button" onClick={onClose}>Cancelar</button><button className="primary">Registrar evento</button></div></form></div>}
function GlobalSearch({onClose,onNavigate,onResident,user}:{onClose:()=>void,onNavigate:(module:Module)=>void,onResident:(resident:string)=>void,user:DemoUser}){const [query,setQuery]=useState('');const items=[...getNav(user).map(n=>({label:n.label,detail:'Ir al módulo',action:()=>onNavigate(n.id)})),...people.map(p=>({label:p.name,detail:'Habitación '+p.room+' · '+p.risk,action:()=>onResident(p.name)}))];const found=query.trim()?items.filter(i=>(i.label+' '+i.detail).toLowerCase().includes(query.toLowerCase())):items;return <div className="modal-backdrop search-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section className="global-search" role="dialog" aria-modal="true" aria-label="Búsqueda global"><div className="search-field"><Search size={20}/><input autoFocus value={query} onChange={e=>setQuery(e.target.value)} placeholder="Buscar residente, habitación o módulo"/><button onClick={onClose} aria-label="Cerrar búsqueda"><X/></button></div><div className="search-results">{found.map(item=><button key={item.label} onClick={()=>{item.action();onClose()}}><span><b>{item.label}</b><small>{item.detail}</small></span>→</button>)}{found.length===0&&<p>No se encontraron resultados.</p>}</div></section></div>}

function Login({onLogin}:{onLogin:(user:DemoUser)=>void}){const [email,setEmail]=useState('admin@serena.demo');const [password,setPassword]=useState('AdminDemo2026!');const [error,setError]=useState('');const submit=(e:React.FormEvent)=>{e.preventDefault();const user=demoUsers.find(u=>u.email===email&&u.password===password);if(!user){setError('Usuario o contraseña incorrectos');return}onLogin(user)};return <div className="login-page"><section className="login-brand"><span className="brandmark">S</span><h1>Serena</h1><p>Gestión integral para residencias</p><small>ENTORNO DE DEMOSTRACIÓN · DATOS FICTICIOS</small></section><form className="login-card" onSubmit={submit}><span className="eyebrow">ACCESO AL SISTEMA</span><h2>Iniciar sesión</h2><p>Ingresá con uno de los perfiles de demostración.</p><label>Correo electrónico<input type="email" value={email} onChange={e=>setEmail(e.target.value)} autoComplete="username"/></label><label>Contraseña<input type="password" value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password"/></label>{error&&<div className="login-error">{error}</div>}<button type="submit">Ingresar</button><div className="demo-access"><b>Accesos rápidos</b>{demoUsers.map(u=><button type="button" key={u.email} onClick={()=>{setEmail(u.email);setPassword(u.password)}}><span>{u.initials}</span><div>{u.role}<small>{u.email}</small></div></button>)}</div></form></div>}
function PrivacyNotice({onClose}:{onClose:()=>void}){return <div className="privacy-backdrop"><section className="privacy-notice" role="dialog" aria-modal="true" aria-labelledby="privacy-title"><div className="privacy-head"><span>AVISO DE PRIVACIDAD Y CONFIDENCIALIDAD</span><button onClick={onClose} aria-label="Cerrar aviso"><X/></button></div><div className="privacy-body"><h2 id="privacy-title">Protección de datos personales</h2><p>Este sistema puede contener datos personales y datos de salud, considerados sensibles por la Ley argentina 25.326. El acceso está limitado a tareas autorizadas y toda consulta o modificación debe responder a una finalidad asistencial o administrativa legítima.</p><ul><li>No compartas información por canales no autorizados.</li><li>No descargues, fotografíes ni copies datos sin justificación.</li><li>Cerrá la sesión al terminar y reportá accesos o incidentes sospechosos.</li><li>Esta demostración utiliza exclusivamente información ficticia.</li></ul><p className="privacy-foot">Al continuar declarás haber leído el aviso. El cierre queda registrado para esta sesión de demostración.</p></div><button className="privacy-accept" onClick={onClose}>Entendido, continuar</button></section></div>}
function App(){
 const [active,setActive]=useState<Module>('resumen');const [user,setUser]=useState<DemoUser|null>(null);const [privacyOpen,setPrivacyOpen]=useState(false);const [searchOpen,setSearchOpen]=useState(false);const [alertsOpen,setAlertsOpen]=useState(false);const [eventOpen,setEventOpen]=useState(false);const [toast,setToast]=useState('');const [hceResident,setHceResident]=useState(people[0].name);const [careKind,setCareKind]=useState<'Catarsis'|'Baño'|'Caída'|'Curación'|null>(null);
 const navigate=(module:Module)=>{setActive(module);setAlertsOpen(false)};const openResidentHce=(resident:string)=>{setHceResident(resident);setActive('hce')};const openCare=(kind:'Catarsis'|'Baño'|'Caída'|'Curación')=>{setCareKind(kind);setActive('cuidados')};
 const content=useMemo(()=>!user?null:active==='resumen'?<Dashboard go={navigate} onNewEvent={()=>setEventOpen(true)} onCare={openCare} user={user}/>:active==='medicacion'?<Medication user={user}/>:active==='controles'?<Controls user={user}/>:active==='residentes'?<Residents onOpenHce={openResidentHce} user={user}/>:active==='hce'?<ClinicalHistory user={user} resident={hceResident}/>:<CareRecords initialKind={careKind} onKindUsed={()=>setCareKind(null)} user={user}/>,[active,user,hceResident,careKind]);
 if(!user)return <Login onLogin={u=>{setUser(u);setPrivacyOpen(true)}}/>;
 return <><Header active={active} setActive={navigate} user={user} onUpdateUser={setUser} onSearch={()=>setSearchOpen(true)} onAlerts={()=>setAlertsOpen(!alertsOpen)} onLogout={()=>{setUser(null);setActive('resumen')}}/>{content}<AlertDock open={alertsOpen} onClose={()=>setAlertsOpen(false)} onNavigate={navigate}/>{searchOpen&&<GlobalSearch onClose={()=>setSearchOpen(false)} onNavigate={navigate} onResident={openResidentHce} user={user}/>} {eventOpen&&<EventEditor onClose={()=>setEventOpen(false)} onSave={message=>{setToast(message);setEventOpen(false);window.setTimeout(()=>setToast(''),3500)}}/>}{toast&&<div className="toast"><Check size={18}/>{toast}</div>}{privacyOpen&&<PrivacyNotice onClose={()=>setPrivacyOpen(false)}/>}</>
}
createRoot(document.getElementById('root')!).render(<App/>);
